'use strict';
const A=window.ATLAS,B=A.bags,M=A.meta,S=A.sources,BASE=document.body.dataset.base||'',PAGE=document.body.dataset.page,Q=new URLSearchParams(location.search),$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n).toLocaleString('it-IT',{maximumFractionDigits:2}),get=id=>B.find(b=>b.id===id)||B[0],link=b=>BASE+'schede/'+b.id+'.html',pic=b=>BASE+'assets/'+b.id+'.svg';
const cats=[...new Set(B.map(b=>b.category))],shapes=[...new Set(B.map(b=>b.shape))].sort(),brands=[...new Set(B.map(b=>b.brand))].sort();
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem('forme-'+k))??d}catch{return d}},save=(k,v)=>{try{localStorage.setItem('forme-'+k,JSON.stringify(v))}catch{}};
let favorites=read('favorites',[]),comp=read('compare',[]),seen=read('seen',[]);
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function download(name,content,type='text/plain'){let url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function options(list,v){return list.map(x=>`<option value="${E(x)}" ${x===v?'selected':''}>${E(x)}</option>`).join('')}
function bagOptions(v){return B.map(b=>`<option value="${b.id}" ${v===b.id?'selected':''}>${E(b.brand+' · '+b.name)}</option>`).join('')}
function tag(b){return `<span class="tag ${b.dimensionStatus==='documentate'?'ok':'warn'}">Quote ${b.dimensionStatus==='documentate'?'documentate':'di studio'}</span>`}
function intro(k,title,desc){return `<div class="eyebrow">${k}</div><h1>${title}</h1><p class="lead">${desc}</p>`}
function hint(t){return `<div class="hint"><strong>Suggerimento</strong> · ${t}</div>`}
function legend(){return `<div class="legend">${cats.map(c=>`<span><i style="background:${B.find(b=>b.category===c).color}"></i>${c}</span>`).join('')}</div>`}
function sourceLinks(ids){return ids.map(k=>S[k]?`<div><a href="${E(S[k].url)}" target="_blank" rel="noopener">${E(S[k].title)} ↗</a><small>${E(S[k].scope)}</small></div>`:'').join('')}
function metrics(b){return Object.entries(b.features).map(([k,v])=>`<div class="meter"><span>${M.featureLabels[k]}</span><div class="bar"><i style="width:${v*20}%"></i></div><span>${v}/5</span></div>`).join('')}
function card(b){return `<article class="card"><span class="number">${String(b.index).padStart(3,'0')}</span><a class="card-picture" href="${link(b)}"><img loading="lazy" src="${pic(b)}" alt="Schema analitico: ${E(b.brand+' '+b.name)}"></a><div class="card-body"><span class="brandname">${E(b.brand)}</span><h3><a href="${link(b)}">${E(b.name)}</a></h3><p>${E(b.sign)}</p><div class="card-actions"><a href="${link(b)}">Esplora la scheda ↗</a><button class="save" data-save="${b.id}" aria-label="${favorites.includes(b.id)?'Rimuovi dai':'Aggiungi ai'} preferiti">${favorites.includes(b.id)?'★':'☆'}</button><button class="ghost small" data-compare="${b.id}" aria-label="Confronta ${E(b.name)}">⇄</button></div></div></article>`}
function wireCards(){ $$('[data-save]').forEach(el=>el.onclick=()=>{let id=el.dataset.save;favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];save('favorites',favorites);el.textContent=favorites.includes(id)?'★':'☆';el.setAttribute('aria-label',favorites.includes(id)?'Rimuovi dai preferiti':'Aggiungi ai preferiti');toast(favorites.includes(id)?'Aggiunta al taccuino':'Rimossa dal taccuino')});$$('[data-compare]').forEach(el=>el.onclick=()=>{let id=el.dataset.compare;if(comp.includes(id))comp=comp.filter(x=>x!==id);else comp=[...comp.slice(-1),id];save('compare',comp);tray()})}
function tray(){document.querySelector('.compare-tray')?.remove();if(!comp.length)return;let el=document.createElement('div');el.className='compare-tray';el.innerHTML=`<span>${comp.map(id=>E(get(id).name)).join(' ↔ ')}${comp.length===1?' · scegli una seconda borsa':''}</span>${comp.length===2?`<a href="${BASE}confronto.html?a=${comp[0]}&b=${comp[1]}">Confronta →</a>`:''}<button class="ghost" aria-label="Svuota confronto">×</button>`;document.body.append(el);el.querySelector('button').onclick=()=>{comp=[];save('compare',comp);tray()}}
const nav=[['index.html','catalogo','Atlante'],['mappe.html','mappe','PCA / 2D–3D'],['rete.html','rete','Rete'],['confronto.html','confronto','Confronto'],['geografia.html','geografia','Geografia'],['laboratorio.html','laboratorio','Atelier'],['metodo.html','metodo','Metodo']];
$('#header').innerHTML=`<a class="brand" href="${BASE}index.html">FORME<small>ATLANTE DELLE BORSE</small></a><nav aria-label="Navigazione principale">${nav.map(([f,p,t])=>`<a href="${BASE+f}" class="${PAGE===p?'active':''}">${t}</a>`).join('')}</nav>`;
$('#footer').innerHTML=`<span>FORME · 200 oggetti, molte storie. Edizione di studio · 30 settembre 2026</span><span><a href="${BASE}metodo.html">Fonti, limiti e dati aperti dell’atlante ↗</a></span>`;
const main=$('#main');

function catalog(){main.innerHTML=`<section class="hero"><div><div class="eyebrow">Un archivio da esplorare / 001—200</div><h1>Le forme<br>del desiderio.</h1><p class="lead">Duecento borse per leggere il rapporto tra oggetto, identità e cultura. Dai codici della selleria alle superfici sperimentali: osserva, confronta, scomponi.</p><div class="row"><a class="btn" href="#catalogo">Esplora l’atlante ↓</a><a class="btn ghost" href="mappe.html">Entra nello spazio del design ↗</a></div><div class="stats"><div><strong>200</strong><span>Famiglie selezionate</span></div><div><strong>${brands.length}</strong><span>Marchi</span></div><div><strong>3</strong><span>Letture PCA</span></div></div><p class="caption">Selezione curatoriale, non classifica universale. Disegni analitici originali; quote documentate e ipotesi di studio sempre separate.</p></div><div class="hero-art"><span class="hero-stamp">01 / 200</span><img src="assets/hermes-birkin.svg" alt="Studio geometrico della Birkin"></div></section><section id="catalogo"><div class="row between"><div><div class="eyebrow">Archivio consultabile</div><h2>Scegli il tuo punto di vista.</h2></div><a href="metodo.html" class="small">Come è costruita la selezione ↗</a></div><div class="toolbar"><label class="search">Cerca nell’atlante<input id="search" type="search" placeholder="Borsa, maison, materiale, dettaglio…"></label><label>Maison<select id="brand"><option value="">Tutte le maison</option>${options(brands,Q.get('brand'))}</select></label><label>Forma<select id="shape"><option value="">Tutte le forme</option>${options(shapes)}</select></label><label>Ordina<select id="sort"><option value="index">Percorso curatoriale</option><option value="name">Nome A–Z</option><option value="year">Cronologia indicativa</option><option value="brand">Maison A–Z</option></select></label></div><div class="chips" id="categories"><button class="chip active" data-cat="">Tutto</button>${cats.map(c=>`<button class="chip" data-cat="${c}">${c}</button>`).join('')}<button class="chip" data-cat="favorites">★ Il mio taccuino</button><button class="chip" data-cat="verified">Quote documentate</button><button class="chip" data-cat="history">Episodi documentati</button></div><div class="statusline" id="count"></div><div class="cards" id="cards"></div><div class="row" style="justify-content:center;margin-top:30px"><button id="more" class="ghost">Mostra altre 24 borse ↓</button></div></section>${hint('Parti da una forma — per esempio la mezzaluna — e osserva come materiale, ferramenta e contesto ne cambiano il significato. Il pulsante ⇄ prepara un confronto diretto.')}<div class="grid3 section"><a class="panel" href="mappe.html"><div class="eyebrow">01 / Analizzare</div><h3>La mappa delle differenze</h3><p class="note">Tre PCA con variabili, coefficienti e varianza spiegata consultabili.</p></a><a class="panel" href="laboratorio.html"><div class="eyebrow">02 / Costruire</div><h3>Dalla superficie al volume</h3><p class="note">Duecento schemi geometrici modificabili, con SVG e DXF scaricabili.</p></a><a class="panel" href="rete.html"><div class="eyebrow">03 / Collegare</div><h3>Affinità inattese</h3><p class="note">Vicinanze calcolate sulle caratteristiche. Esportazione Gephi, GraphML e GXL.</p></a></div>`;
 let category='',limit=24,filtered=[];function render(){let q=$('#search').value.toLowerCase(),brand=$('#brand').value,shape=$('#shape').value;filtered=B.filter(b=>(!brand||b.brand===brand)&&(!shape||b.shape===shape)&&(!q||[b.brand,b.name,b.material,b.hardware,b.sign].join(' ').toLowerCase().includes(q))&&(!category||b.category===category||category==='favorites'&&favorites.includes(b.id)||category==='verified'&&b.dimensionStatus==='documentate'||category==='history'&&b.events.length));let sort=$('#sort').value;filtered.sort((a,b)=>sort==='year'?(a.year||9999)-(b.year||9999):sort==='brand'?a.brand.localeCompare(b.brand):sort==='name'?a.name.localeCompare(b.name):a.index-b.index);$('#count').textContent=`${filtered.length} borse · ${Math.min(limit,filtered.length)} visualizzate`+ (sort==='year'?' · le date non verificate restano indicative':'');$('#cards').innerHTML=filtered.slice(0,limit).map(card).join('')||'<div class="empty">Nessuna borsa corrisponde ai filtri. Prova a cambiare ricerca.</div>';$('#more').hidden=filtered.length<=limit;wireCards()}
 ['search','brand','shape','sort'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',()=>{limit=24;render()}));$$('[data-cat]').forEach(el=>el.onclick=()=>{category=el.dataset.cat;$$('[data-cat]').forEach(e=>e.classList.toggle('active',e===el));limit=24;render()});$('#more').onclick=()=>{limit+=24;render()};render();window.__catalog={render,get filtered(){return filtered}};
}

function sheet(){let b=get(document.body.dataset.id);if(!seen.includes(b.id)){seen.push(b.id);save('seen',seen)}let near=B.filter(x=>x!==b).map(x=>[x,BagAnalysis.similarity(b,x)]).sort((a,c)=>c[1]-a[1]).slice(0,4);main.innerHTML=`<div class="breadcrumb"><a href="../index.html">Atlante</a> / ${E(b.brand)} / ${E(b.name)} <span style="float:right">${String(b.index).padStart(3,'0')} / 200</span></div><section class="sheet-hero"><div class="image"><img src="${pic(b)}" alt="Illustrazione analitica di ${E(b.name)}"></div><div><div class="eyebrow">${b.category} · ${b.shape}</div><div class="brandname">${E(b.brand.toUpperCase())}</div><h1>${E(b.name)}</h1><p class="lead">${E(b.sign[0].toUpperCase()+b.sign.slice(1))}.</p><div class="row">${tag(b)}<span class="tag">${b.historyStatus}</span></div><div class="specs"><div class="spec"><small>L × H × P · cm</small><strong>${b.dims.map(fmt).join(' × ')}</strong></div><div class="spec"><small>Riferimento cronologico</small><strong>${b.year||'Non accertato'} · ${b.yearStatus}</strong></div><div class="spec"><small>Materia di riferimento</small><strong>${E(b.material)}</strong></div><div class="spec"><small>Hardware / accessori</small><strong>${E(b.hardware)}</strong></div></div><p class="dim-caption">${E(b.variant)}. ${b.dimensionStatus==='documentate'?'Quote riferite solo alla variante indicata.':'Queste quote sono assunzioni per visualizzazione e prototipazione, non misure del produttore.'}</p><div class="row"><a class="btn" href="../laboratorio.html?id=${b.id}">Apri l’atelier 3D ↗</a><button class="ghost" data-compare="${b.id}">⇄ Confronta</button><button class="save" data-save="${b.id}" aria-label="Salva nel taccuino">${favorites.includes(b.id)?'★':'☆'}</button></div></div></section><div class="quicklinks"><a href="#lettura">Lettura del progetto</a><a href="#storia">Storia e contesto</a><a href="#dati">Profilo analitico</a><a href="#fonti">Fonti e attendibilità</a><button class="ghost small" id="print">Stampa scheda / PDF</button></div><section id="lettura" class="section grid2"><div class="panel"><div class="eyebrow">01 / Forma e significato</div><h2>${b.title}</h2><p>${b.structure}</p><h3>Il segno distintivo</h3><p>In ${E(b.name)}, ${E(b.sign)}: è questo il dettaglio su cui si concentra la lettura curatoriale. Non basta la categoria «${b.shape}» a descriverne l’identità.</p><p class="note">Lettura semantica editoriale: ${b.semantics}</p></div><div class="panel"><div class="eyebrow">02 / Perché nell’atlante</div><h2>Una ragione per ricordarla.</h2><p>${E(b.reason)}</p><h3>Materiale e costruzione</h3><p>${b.materialNote}</p></div></section><section id="storia" class="section grid2"><div class="panel"><div class="eyebrow">03 / Storia e contesto</div><h2>Gli episodi documentati</h2>${b.events.length?`<div class="timeline">${b.events.map(([d,t])=>`<div class="event"><b>${E(d)}</b><p>${E(t)}</p></div>`).join('')}</div>`:`<p>Non è stato consolidato un episodio storico specifico per questa scheda. ${b.year?`Il riferimento ${b.year} è un appunto cronologico da verificare, non una data certificata di lancio.`:''}</p><p class="note">La scelta curatoriale è motivata dai codici di progetto riportati sopra. Non vengono attribuite apparizioni cinematografiche, celebrità o primati senza riscontro.</p>`}<p class="caption">Date di sfilata, vendita, riedizione e antecedente non sono equivalenti. Ogni episodio va letto nel perimetro della fonte.</p></div><div class="panel dark"><div class="eyebrow light">04 / Esercizio di lettura</div><h2>Cosa resta senza il nome?</h2><p>${E(b.question)}</p><div class="quiz" id="quiz"><p class="caption">Quale descrizione coglie meglio il codice selezionato per questa borsa?</p><div id="answers"></div><div class="result" id="feedback" aria-live="polite"></div></div><p class="caption" style="margin-top:20px">Le attività guidano l’osservazione; non misurano il valore commerciale.</p></div></section><section id="dati" class="section grid2"><div class="panel"><div class="eyebrow">05 / Profilo analitico</div><h2>Il vocabolario numerico</h2>${metrics(b)}<p class="caption">Punteggi ordinali 1–5, attribuiti con regole editoriali. La PCA tratta gli intervalli come equidistanti: ipotesi esplorativa, non misurazione psicometrica.</p><a class="btn ghost" href="../mappe.html?id=${b.id}">Localizza nella PCA ↗</a></div><div class="panel"><div class="eyebrow">06 / Geometria e prototipo</div><h2>Una forma da interrogare</h2><p>Il laboratorio ricostruisce una variante semplificata con due pannelli e una fascia perimetrale. Puoi cambiare ingombro e margine, ruotare il volume e separarne le parti.</p><p class="note">Per ${E(b.name)} lo schema studia il profilo ${b.shape}. Non ricostruisce la distinta base originale, i meccanismi proprietari o il comportamento del materiale.</p><div class="row"><a class="btn" href="../laboratorio.html?id=${b.id}">Modifica il modello</a><a class="btn ghost" href="../cartamodelli/${b.id}.svg" download>SVG 1:1 ↓</a></div></div></section><section id="fonti" class="section panel"><div class="eyebrow">07 / Provenienza</div><h2>Fonti e perimetro delle affermazioni</h2><div class="sources">${sourceLinks(b.sources)}</div>${!b.sources.length?'<p>Nessuna fonte specifica consolidata per questo modello nell’edizione corrente.</p>':''}<p class="note">Una fonte di famiglia o di marchio non certifica automaticamente ogni dato della scheda. Materie e accessori descrivono un archetipo rappresentativo; composizioni, dimensioni e dettagli possono cambiare tra varianti. I disegni sono interpretazioni originali. Ultima consultazione delle fonti: 30 settembre 2026.</p><a href="${E(A.brands[b.brand].url)}" target="_blank" rel="noopener" class="btn ghost">Sito della maison · approfondisci ↗</a></section><section class="section"><div class="row between"><h2>Vicini per caratteristiche</h2><a href="../rete.html?id=${b.id}">Esplora la rete ↗</a></div><div class="cards">${near.map(([x])=>card(x)).join('')}</div></section>${hint('Nella PCA, cambia da «Semantica» a «Materiali»: una vicinanza può scomparire se cambia la domanda di ricerca.')}`;
 let answers=[b.sign,get(B[(b.index+33)%B.length].id).sign,get(B[(b.index+78)%B.length].id).sign].map((text,i)=>({text,correct:i===0}));answers.sort((a,c)=>a.text.localeCompare(c.text));$('#answers').innerHTML=answers.map((a,i)=>`<button class="ghost" data-answer="${i}" style="color:#eee;border-color:#698783">${E(a.text)}</button>`).join('');$$('[data-answer]').forEach(el=>el.onclick=()=>{let good=answers[+el.dataset.answer].correct;$('#feedback').textContent=good?'Esatto. Ora prova a spiegare come questo dettaglio cambia uso e significato.':'Rileggi il segno distintivo: cerca una caratteristica specifica, non soltanto il materiale.';if(good){let done=read('quiz',[]);if(!done.includes(b.id)){done.push(b.id);save('quiz',done)}}});$('#print').onclick=()=>window.print();wireCards();window.__sheet=b;
}

function comparison(){let a=get(Q.get('a')||comp[0]),b=get(Q.get('b')||comp[1]||'chanel-2-55');main.innerHTML=intro('Confronto / due punti di vista','Metti le differenze<br>una accanto all’altra.','Confronta materia, proporzioni, codici visivi ed evidenze storiche. La somiglianza dipende dalle variabili scelte.')+`<div class="toolbar"><label>Prima borsa<select id="a">${bagOptions(a.id)}</select></label><button class="ghost" id="swap" aria-label="Scambia le borse">⇄</button><label>Seconda borsa<select id="b">${bagOptions(b.id)}</select></label><button id="comparecsv" class="ghost">Esporta confronto CSV ↓</button></div><div id="comparison"></div>`;
 function render(){a=get($('#a').value);b=get($('#b').value);let sim=BagAnalysis.similarity(a,b);$('#comparison').innerHTML=`<div class="grid2">${[a,b].map(x=>`<div><div class="compare-art"><img src="${pic(x)}" alt="Schema ${E(x.name)}"></div><div class="compare-title"><div><div class="eyebrow" style="margin:12px 0 5px">${E(x.brand)}</div><h2><a href="${link(x)}">${E(x.name)} ↗</a></h2></div>${tag(x)}</div></div>`).join('')}</div><div class="grid3 section"><div class="panel"><div class="eyebrow">Affinità Gower</div><div class="callout-number">${fmt(sim*100)}%</div><p class="note">Su otto codici editoriali 1–5. Non è una probabilità di parentela né una valutazione di qualità.</p></div><div class="panel"><div class="eyebrow">Punto di contatto</div><h3>${a.shape===b.shape?'Stesso archetipo: '+a.shape:'Due forme: '+a.shape+' / '+b.shape}</h3><p class="note">${a.material===b.material?'Condividono la famiglia materica scelta.':'Le materie di riferimento differiscono: '+E(a.material)+' e '+E(b.material)+'.'}</p></div><div class="panel"><div class="eyebrow">Domanda di progetto</div><h3>Un dettaglio può cambiare tutto?</h3><p class="note">Confronta ${E(a.hardware)} con ${E(b.hardware)}: osserva la relazione tra chiusura, gesto e riconoscibilità.</p></div></div><section class="section panel table-wrap"><table><thead><tr><th>Caratteristica</th><th>${E(a.name)}</th><th>${E(b.name)}</th></tr></thead><tbody>${[['Materia','material'],['Hardware','hardware'],['Segno','sign'],['Forma','shape'],['Lettura semantica','semantics'],['Motivo della selezione','reason'],['Stato della cronologia','historyStatus']].map(([t,k])=>`<tr><th>${t}</th><td>${E(a[k])}</td><td>${E(b[k])}</td></tr>`).join('')}<tr><th>L × H × P · cm</th><td>${a.dims.map(fmt).join(' × ')}<br>${a.dimensionStatus}</td><td>${b.dims.map(fmt).join(' × ')}<br>${b.dimensionStatus}</td></tr><tr><th>Variante</th><td>${E(a.variant)}</td><td>${E(b.variant)}</td></tr><tr><th>Episodi documentati</th><td>${a.events.map(e=>E(e.join(' · '))).join('<br><br>')||'Non consolidati'}</td><td>${b.events.map(e=>E(e.join(' · '))).join('<br><br>')||'Non consolidati'}</td></tr></tbody></table></section><section class="section grid2"><div class="panel"><h2>Profili sovrapposti</h2><canvas id="radar" style="width:100%;height:330px" aria-label="Radar dei punteggi editoriali"></canvas><div class="legend"><span><i style="background:#ae5b3c"></i>${E(a.name)}</span><span><i style="background:#326b70"></i>${E(b.name)}</span></div></div><div class="panel"><h2>Le distanze leggibili</h2>${Object.entries(M.featureLabels).map(([k,t])=>`<div class="meter"><span>${t}</span><span>${a.features[k]} / ${b.features[k]}</span><b>${Math.abs(a.features[k]-b.features[k])}</b></div>`).join('')}<p class="caption">Colonna finale: differenza assoluta su una scala 1–5.</p><div class="row"><a class="btn ghost" href="laboratorio.html?id=${a.id}">Atelier A</a><a class="btn ghost" href="laboratorio.html?id=${b.id}">Atelier B</a></div></div></section>${hint('Per confrontare gli ingombri, usa le tre quote separatamente. Il prodotto L × H × P è un volume della scatola esterna: non coincide con la capacità utile della borsa.')}`;radar($('#radar'),[a,b]);history.replaceState(null,'','?a='+a.id+'&b='+b.id)}
 $('#a').onchange=render;$('#b').onchange=render;$('#swap').onclick=()=>{let t=$('#a').value;$('#a').value=$('#b').value;$('#b').value=t;render()};$('#comparecsv').onclick=()=>download('confronto-borse.csv','\ufeff'+[['campo',a.brand+' '+a.name,b.brand+' '+b.name],...['material','hardware','shape','sign','dimensionStatus','variant','historyStatus'].map(k=>[k,a[k],b[k]]),...Object.keys(M.featureLabels).map(k=>[M.featureLabels[k],a.features[k],b.features[k]]),...['L','H','P'].map((v,i)=>[v+' cm',a.dims[i],b.dims[i]])].map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n'),'text/csv');render();window.__compare={get a(){return a},get b(){return b}};
}
function radar(canvas,bs){let dpr=devicePixelRatio||1,W=canvas.clientWidth||500,H=330;canvas.width=W*dpr;canvas.height=H*dpr;let c=canvas.getContext('2d');c.scale(dpr,dpr);let cx=W/2,cy=H/2,r=Math.min(W*.3,110),keys=Object.keys(M.featureLabels);for(let level=1;level<=5;level++){c.beginPath();keys.forEach((k,i)=>{let t=i/8*Math.PI*2-Math.PI/2,x=cx+Math.cos(t)*r*level/5,y=cy+Math.sin(t)*r*level/5;i?c.lineTo(x,y):c.moveTo(x,y)});c.closePath();c.strokeStyle='#d6dacc';c.stroke()}keys.forEach((k,i)=>{let t=i/8*Math.PI*2-Math.PI/2;c.fillStyle='#526966';c.font='10px Arial';c.textAlign=Math.cos(t)>.2?'left':Math.cos(t)<-.2?'right':'center';c.fillText(M.featureLabels[k],cx+Math.cos(t)*(r+12),cy+Math.sin(t)*(r+12)+4)});bs.forEach((b,j)=>{c.beginPath();keys.forEach((k,i)=>{let t=i/8*Math.PI*2-Math.PI/2,x=cx+Math.cos(t)*r*b.features[k]/5,y=cy+Math.sin(t)*r*b.features[k]/5;i?c.lineTo(x,y):c.moveTo(x,y)});c.closePath();c.fillStyle=j?'#326b7025':'#ae5b3c25';c.strokeStyle=j?'#326b70':'#ae5b3c';c.lineWidth=2;c.fill();c.stroke()})}

