function canvasPlot(host,points,onSelect,{edges=[],dark=false,labels=false}={}){
 host.querySelector('canvas')?.remove();let canvas=document.createElement('canvas');canvas.tabIndex=0;canvas.setAttribute('aria-label','Grafico interattivo; trascina per spostare, rotella per zoomare. Usa anche la lista di selezione.');host.prepend(canvas);let c=canvas.getContext('2d'),W,H,dpr,zoom=1,pan=[0,0],hit=[],selected='',drag=null,moved=false;
 function resize(){W=host.clientWidth;H=host.clientHeight;dpr=devicePixelRatio||1;canvas.width=W*dpr;canvas.height=H*dpr;draw()}
 function coord(p){return [W/2+(p.x*W*.39+pan[0])*zoom,H/2+(p.y*H*.38+pan[1])*zoom]}
 function draw(){c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,W,H);c.fillStyle=dark?'#163438':'#eaece2';c.fillRect(0,0,W,H);c.strokeStyle=dark?'#ffffff10':'#526c6415';c.lineWidth=1;for(let i=-4;i<=4;i++){let x=W/2+i*W*.1*zoom+pan[0]*zoom,y=H/2+i*H*.1*zoom+pan[1]*zoom;c.beginPath();c.moveTo(x,0);c.lineTo(x,H);c.moveTo(0,y);c.lineTo(W,y);c.stroke()}
 const map=new Map(points.map(p=>[p.b.id,p]));for(let e of edges){let a=map.get(e.source),b=map.get(e.target);if(!a||!b)continue;let [x,y]=coord(a),[u,v]=coord(b);c.beginPath();c.moveTo(x,y);c.lineTo(u,v);c.strokeStyle=selected&&(e.source===selected||e.target===selected)?'#d2b56dbb':dark?'#9fc1b527':'#4d75652e';c.lineWidth=selected&&(e.source===selected||e.target===selected)?1.7:.7;c.stroke()}
 hit=[];for(let p of points){let [x,y]=coord(p),r=p.b.id===selected?7:4;c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.fillStyle=p.b.color;c.fill();c.strokeStyle=p.b.id===selected?'#f7e6b6':dark?'#142f31':'#f4f0e7';c.lineWidth=p.b.id===selected?2.5:1;c.stroke();hit.push({x,y,p});if(labels||p.b.id===selected){c.fillStyle=dark?'#e3e7d8':'#294b48';c.font='10px Arial';c.fillText(p.b.name,x+9,y-7)}}}
 const tooltip=document.createElement('div');tooltip.className='tooltip';document.body.append(tooltip);canvas.onpointerdown=e=>{drag=[e.clientX,e.clientY,...pan];moved=false;canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{let rect=canvas.getBoundingClientRect(),x=e.clientX-rect.left,y=e.clientY-rect.top;if(drag){let dx=e.clientX-drag[0],dy=e.clientY-drag[1];if(Math.abs(dx)+Math.abs(dy)>4)moved=true;pan=[drag[2]+dx/zoom,drag[3]+dy/zoom];draw();tooltip.style.display='none';return}let h=hit.reduce((best,h)=>Math.hypot(h.x-x,h.y-y)<12&&(!best||Math.hypot(h.x-x,h.y-y)<best.d)?{...h,d:Math.hypot(h.x-x,h.y-y)}:best,null);canvas.style.cursor=h?'pointer':'grab';tooltip.style.display=h?'block':'none';if(h){tooltip.textContent=h.p.b.brand+' · '+h.p.b.name;tooltip.style.left=Math.min(innerWidth-240,e.clientX+12)+'px';tooltip.style.top=e.clientY+12+'px'}};canvas.onpointerup=e=>{drag=null;if(moved)return;let rect=canvas.getBoundingClientRect(),x=e.clientX-rect.left,y=e.clientY-rect.top,h=hit.filter(h=>Math.hypot(h.x-x,h.y-y)<15).sort((a,b)=>Math.hypot(a.x-x,a.y-y)-Math.hypot(b.x-x,b.y-y))[0];if(h){selected=h.p.b.id;draw();onSelect(h.p.b)}};canvas.onpointerleave=()=>tooltip.style.display='none';canvas.onwheel=e=>{e.preventDefault();zoom=Math.max(.4,Math.min(6,zoom*Math.exp(-e.deltaY*.001)));draw()};let ro=new ResizeObserver(resize);ro.observe(host);resize();return {canvas,select(id){selected=id;draw()},reset(){zoom=1;pan=[0,0];draw()},destroy(){ro.disconnect();tooltip.remove();canvas.remove()},get positions(){return Object.fromEntries(points.map(p=>[p.b.id,[p.x*100,p.y*100]]))}};
}

function threeScatter(host,points,onSelect){
 host.querySelector('canvas')?.remove();let T=window.THREE,scene=new T.Scene();scene.background=new T.Color('#163438');let camera=new T.PerspectiveCamera(42,1,.1,100),renderer;
 try{renderer=new T.WebGLRenderer({antialias:true,preserveDrawingBuffer:true})}catch{host.insertAdjacentHTML('beforeend','<p class="panel">Il browser non espone WebGL. Usa la vista 2D.</p>');return {destroy(){},select(){},reset(){}}}
 renderer.setPixelRatio(Math.min(devicePixelRatio,2));host.prepend(renderer.domElement);let group=new T.Group();scene.add(group);let spheres=[],geo=new T.SphereGeometry(.043,12,8);points.forEach(p=>{let mesh=new T.Mesh(geo,new T.MeshBasicMaterial({color:p.b.color}));mesh.position.set(p.x*2.5,-p.y*2.5,p.z*2.5);mesh.userData.b=p.b;group.add(mesh);spheres.push(mesh)});let axes=new T.AxesHelper(3);group.add(axes);let grid=new T.GridHelper(6,12,0x65887d,0x31514e);grid.position.y=-2.7;group.add(grid);let yaw=.35,pitch=.22,distance=8,drag=null,moved=false,frame,selected;const ray=new T.Raycaster();
 function draw(){camera.position.set(distance*Math.sin(yaw)*Math.cos(pitch),distance*Math.sin(pitch),distance*Math.cos(yaw)*Math.cos(pitch));camera.lookAt(0,0,0);renderer.render(scene,camera);frame=requestAnimationFrame(draw)}function resize(){let w=host.clientWidth,h=host.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix()};let ro=new ResizeObserver(resize);ro.observe(host);resize();draw();let cv=renderer.domElement;cv.onpointerdown=e=>{drag=[e.clientX,e.clientY,yaw,pitch];moved=false;cv.setPointerCapture(e.pointerId)};cv.onpointermove=e=>{if(!drag)return;let dx=e.clientX-drag[0],dy=e.clientY-drag[1];moved=Math.abs(dx)+Math.abs(dy)>4;yaw=drag[2]-dx*.008;pitch=Math.max(-1.3,Math.min(1.3,drag[3]+dy*.008))};cv.onpointerup=e=>{drag=null;if(moved)return;let r=cv.getBoundingClientRect();ray.setFromCamera(new T.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),camera);let h=ray.intersectObjects(spheres)[0];if(h)onSelect(h.object.userData.b)};cv.onwheel=e=>{e.preventDefault();distance=Math.max(3,Math.min(18,distance*Math.exp(e.deltaY*.001)))};return{canvas:cv,scene,camera,select(id){spheres.forEach(s=>s.scale.setScalar(s.userData.b.id===id?2:1));selected=id},reset(){yaw=.35;pitch=.22;distance=8},destroy(){cancelAnimationFrame(frame);ro.disconnect();geo.dispose();spheres.forEach(s=>s.material.dispose());renderer.dispose();cv.remove()}};
}

function maps(){main.innerHTML=intro('Analisi / PCA e variabili','Uno spazio per<br>leggere il progetto.','Ogni punto è una borsa. La PCA riduce le variabili a tre assi: vicinanza e distanza descrivono il campione, non il valore degli oggetti.')+`<div class="toolbar"><label>Insieme di caratteristiche<select id="mode"><option value="semantica">Semantica e codici visivi</option><option value="forma">Forma e quote di studio</option><option value="materiali">Famiglie materiche</option></select></label><label>Rappresentazione<select id="projection"><option value="pca">Componenti principali (PCA)</option><option value="raw">Variabili originali</option></select></label><label>Filtra il campione visibile<select id="filter"><option value="">Tutte le categorie</option>${options(cats)}</select></label><label>Trova una borsa<select id="find">${bagOptions(Q.get('id'))}</select></label></div><div class="viz-tools"><button id="v2" class="ghost active">Vista 2D</button><button id="v3" class="ghost">Vista 3D</button><button id="reset" class="ghost">Centra</button><button id="png" class="ghost">Esporta immagine ↓</button><button id="csv" class="ghost">Dati PCA CSV ↓</button></div><div class="row" id="axes"></div>${legend()}<div class="viz-layout"><div><div id="plot" class="viz"><div class="corner" id="axislabel"></div><div class="bottom">Trascina · rotella per zoomare · clic su un punto</div></div><p class="statusline" id="variance"></p></div><aside id="detail" class="panel detail"></aside></div><section class="section panel"><h2>Cosa significano gli assi?</h2><p class="note" id="mode-note"></p><div class="table-wrap" id="loadings"></div></section>${hint('Confronta la mappa semantica con quella materica. Punti sovrapposti possono avere codifiche identiche: usa «Trova una borsa» per selezionare anche quelli nascosti. I filtri nascondono punti, ma non ricalcolano la PCA sul sottoinsieme.')}`;
 let view='2d',plot,selected=get(Q.get('id')),points=[],current;
 function updateAxes(){let p=A.pca[$('#mode').value];$('#axes').innerHTML=['x','y','z'].map((a,i)=>`<label>Asse ${a.toUpperCase()}<select id="axis-${a}">${p.labels.map((l,j)=>`<option value="${j}" ${j===i?'selected':''}>${E(l)}</option>`).join('')}</select></label>`).join('');$('#axes').style.display=$('#projection').value==='raw'?'flex':'none';$$('#axes select').forEach(el=>el.onchange=render)}
 function select(b){selected=b;$('#find').value=b.id;plot?.select(b.id);detail(b);}
 function render(){plot?.destroy();let mode=$('#mode').value,p=A.pca[mode],raw=$('#projection').value==='raw',axes=['x','y','z'].map(a=>+$('#axis-'+a).value),scores=raw?p.raw.map(r=>axes.map(k=>r[k])):p.scores,max=[0,1,2].map(k=>Math.max(...scores.map(r=>Math.abs(r[k])))),means=raw?[0,1,2].map(k=>scores.reduce((s,r)=>s+r[k],0)/scores.length):[0,0,0];if(raw)max=[0,1,2].map(k=>Math.max(...scores.map(r=>Math.abs(r[k]-means[k]))));points=B.map((b,i)=>({b,x:(scores[i][0]-means[0])/(max[0]||1),y:-(scores[i][1]-means[1])/(max[1]||1),z:(scores[i][2]-means[2])/(max[2]||1)})).filter(p=>!$('#filter').value||p.b.category===$('#filter').value);let is3=view==='3d';$('#plot').classList.toggle('dark',is3);plot=is3?threeScatter($('#plot'),points,select):canvasPlot($('#plot'),points,select);select(selected);$('#axislabel').textContent=raw?'X: '+p.labels[axes[0]]+' / Y: '+p.labels[axes[1]]+(is3?' / Z: '+p.labels[axes[2]]:''):'PC1 orizzontale · PC2 verticale'+(is3?' · PC3 profondità · assi rosso / verde / blu':'');$('#variance').textContent=`${points.length}/200 punti · PC1 ${fmt(p.variance[0])}% · PC2 ${fmt(p.variance[1])}% · PC3 ${fmt(p.variance[2])}% · ${is3?'3':'2'} componenti spiegano ${fmt(p.variance.slice(0,is3?3:2).reduce((a,v)=>a+v,0))}% della varianza.`;$('#mode-note').textContent=mode==='semantica'?'Otto codici editoriali ordinali 1–5, standardizzati. Le distanze dipendono dalle regole di codifica, non da giudizi raccolti tra consumatori.':mode==='forma'?`Sette variabili, incluse quote esterne e rapporti. Solo ${M.dimensionVerified} delle 200 terne dimensionali sono documentate per una variante: questa è soprattutto un’esplorazione delle geometrie di studio.`:'Dieci indicatori binari di presenza delle famiglie materiche. La standardizzazione amplifica anche materiali rari: una grande separazione non implica maggiore importanza culturale.';$('#loadings').innerHTML=`<table><thead><tr><th>Variabile standardizzata</th><th>PC1</th><th>PC2</th><th>PC3</th></tr></thead><tbody>${p.labels.map((l,i)=>`<tr><th>${l}</th>${p.loadings[i].map(v=>`<td style="color:${v<0?'#aa5a3c':'#326b70'}">${v.toFixed(3)}</td>`).join('')}</tr>`).join('')}</tbody></table><p class="caption">Coefficienti degli autovettori della matrice di covarianza dei dati standardizzati (deviazione standard campionaria, n−1). Segno orientato per avere positivo il coefficiente di massima ampiezza. Assi grafici ridimensionati separatamente per leggibilità; non stimare distanze euclidee dal disegno. Nessuna data o stima di notorietà entra nella PCA.</p>`;current=mode}
 $('#mode').onchange=()=>{updateAxes();render()};$('#projection').onchange=()=>{updateAxes();render()};$('#filter').onchange=render;$('#find').onchange=()=>select(get($('#find').value));$('#v2').onclick=()=>{view='2d';$('#v2').classList.add('active');$('#v3').classList.remove('active');render()};$('#v3').onclick=()=>{view='3d';$('#v3').classList.add('active');$('#v2').classList.remove('active');render()};$('#reset').onclick=()=>plot.reset();$('#csv').onclick=()=>{let a=document.createElement('a');a.href=BASE+'dati/pca-'+current+'.csv';a.download='pca-'+current+'.csv';a.click()};$('#png').onclick=()=>{if(!plot.canvas)return;let a=document.createElement('a');a.href=plot.canvas.toDataURL('image/png');a.download='forme-pca-'+current+'-'+view+'.png';a.click()};updateAxes();render();window.__maps={get plot(){return plot},get points(){return points},render};
}

function networkPage(){main.innerHTML=intro('Connessioni / rete esportabile','Le affinità<br>prendono forma.','Una rete di somiglianze calcolate. Puoi usare anche la correlazione di Pearson tra profili: nessun arco prova un’influenza storica o un rapporto tra aziende.')+`<div class="toolbar"><label>Metrica<select id="metric"><option value="gower">Somiglianza Gower · 8 codici</option><option value="pearson">Correlazione Pearson · 8 codici</option><option value="materiali">Jaccard · termini materici</option></select></label><label>Soglia minima <output id="threshold-value">0,84</output><input id="threshold" type="range" min="0" max="1" step=".01" value=".84"></label><label>Vicini per nodo<select id="k"><option value="4">4 vicini · unione</option><option value="8">8 vicini · unione</option><option value="0">Tutti sopra soglia</option></select></label><label>Trova una borsa<select id="find">${bagOptions(Q.get('id'))}</select></label></div><div class="viz-tools"><button id="reset" class="ghost">Centra rete</button><button id="ego" class="ghost">Solo vicinato</button><button data-export="gexf" class="ghost">Gephi · GEXF ↓</button><button data-export="graphml" class="ghost">GraphML ↓</button><button data-export="gxl" class="ghost">GXL ↓</button><button id="edgescsv" class="ghost">Archi CSV ↓</button></div>${legend()}<div class="viz-layout"><div><div class="viz dark" id="net"><div class="corner">RETE DELLE AFFINITÀ / 200 OGGETTI</div><div class="bottom">Trascina per spostare · clic per esplorare · rotella per zoomare</div></div><p id="netstats" class="statusline"></p></div><aside class="panel"><div id="detail" class="detail"></div><h3>Vicini del nodo</h3><div id="neighbors" class="list" style="max-height:280px;overflow:auto"></div></aside></div>${hint('Aumenta la soglia per isolare legami forti. L’esportazione contiene esattamente i nodi e gli archi visualizzati, con nomi, categorie, materiali e pesi. «glx» è interpretato come GXL; per Gephi usa GEXF.')}<section class="panel section"><h2>Come leggere un arco</h2><p id="metricnote"></p><p class="note">L’opzione “4 vicini” conserva l’unione delle prime quattro affinità di ciascun nodo: un nodo può quindi ricevere più di quattro archi. Le parità sono risolte per identificatore. La disposizione iniziale deriva dalla PCA semantica, poi viene rilassata con attrazione e repulsione; le coordinate non sono distanze statistiche.</p></section>`;
 let selected=get(Q.get('id')),ego=false,plot,allEdges=[],shown=[],edges=[],positions={};
 function select(b){selected=b;$('#find').value=b.id;if(ego){render();return}highlight()}
 function highlight(){plot.select(selected.id);detail(selected);let ns=allEdges.filter(e=>e.source===selected.id||e.target===selected.id).map(e=>({b:get(e.source===selected.id?e.target:e.source),weight:e.weight})).sort((a,b)=>b.weight-a.weight);$('#neighbors').innerHTML=ns.length?ns.map(x=>`<button data-node="${x.b.id}">${E(x.b.brand+' · '+x.b.name)} <b>${x.weight.toFixed(2)}</b></button>`).join(''):'<p class="note">Nessun vicino alla soglia attuale. Riduci la soglia.</p>';$$('[data-node]').forEach(e=>e.onclick=()=>select(get(e.dataset.node)))}
 function render(){plot?.destroy();let metric=$('#metric').value,t=+$('#threshold').value,k=+$('#k').value;$('#threshold-value').textContent=t.toFixed(2);allEdges=BagAnalysis.network(B,metric,t,k);let ids=new Set([selected.id]);if(ego)allEdges.forEach(e=>{if(e.source===selected.id)ids.add(e.target);if(e.target===selected.id)ids.add(e.source)});shown=ego?B.filter(b=>ids.has(b.id)):B;edges=allEdges.filter(e=>shown.some(b=>b.id===e.source)&&shown.some(b=>b.id===e.target));let ps=shown.map(b=>{let i=B.indexOf(b),s=A.pca.semantica.scores[i];return{b,x:s[0]*.17+Math.sin(i*2.399)*.04,y:s[1]*.17+Math.cos(i*2.399)*.04}});let idx=new Map(ps.map((p,i)=>[p.b.id,i]));for(let iter=0;iter<80;iter++){let forces=ps.map(()=>[0,0]);for(let i=0;i<ps.length;i++)for(let j=i+1;j<ps.length;j++){let dx=ps[i].x-ps[j].x,dy=ps[i].y-ps[j].y,d2=dx*dx+dy*dy+.005,f=.00012/d2;forces[i][0]+=dx*f;forces[i][1]+=dy*f;forces[j][0]-=dx*f;forces[j][1]-=dy*f}edges.forEach(e=>{let i=idx.get(e.source),j=idx.get(e.target),dx=ps[j].x-ps[i].x,dy=ps[j].y-ps[i].y,d=Math.hypot(dx,dy),f=(d-.14)*.014;forces[i][0]+=dx*f;forces[i][1]+=dy*f;forces[j][0]-=dx*f;forces[j][1]-=dy*f});ps.forEach((p,i)=>{p.x+=(forces[i][0]-p.x*.002);p.y+=(forces[i][1]-p.y*.002)})}let max=Math.max(...ps.flatMap(p=>[Math.abs(p.x),Math.abs(p.y)]),.1);ps.forEach(p=>{p.x/=max;p.y/=max});plot=canvasPlot($('#net'),ps,select,{edges,dark:true});positions=plot.positions;highlight();$('#netstats').textContent=`${shown.length} nodi · ${edges.length} archi · ${shown.filter(b=>!edges.some(e=>e.source===b.id||e.target===b.id)).length} isolati · soglia ${t.toFixed(2)}`;$('#metricnote').textContent=metric==='gower'?'Gower: s = 1 − media(|aᵢ − bᵢ| / 4), su otto scale ordinali da 1 a 5. Tutte le variabili hanno lo stesso peso. Due punteggi identici producono s = 1, anche se le borse hanno storie diverse.':metric==='pearson'?'Pearson: correlazione fra i due profili di otto punteggi, centrati sulla propria media. Qui si visualizzano solo correlazioni non negative sopra soglia. Non è una stima inferenziale: le otto caratteristiche non sono un campione di osservazioni indipendenti.':'Jaccard: intersezione / unione dei termini materici normalizzati. “Trapuntata”, “saffiano”, “intrecciata” e “traforata” vengono esclusi dal confronto dei termini. È una codifica lessicale, non un’analisi chimica dei materiali.'}
 ['metric','threshold','k'].forEach(id=>$('#'+id).onchange=render);$('#threshold').oninput=()=>$('#threshold-value').textContent=(+$('#threshold').value).toFixed(2);$('#find').onchange=()=>select(get($('#find').value));$('#ego').onclick=()=>{ego=!ego;$('#ego').classList.toggle('active',ego);$('#ego').textContent=ego?'Mostra tutta la rete':'Solo vicinato';render()};$('#reset').onclick=()=>plot.reset();$$('[data-export]').forEach(el=>el.onclick=()=>download('forme-rete.'+el.dataset.export,BagAnalysis.exportsGraph(shown,edges,el.dataset.export,positions,{metric:$('#metric').value,threshold:+$('#threshold').value,k:+$('#k').value,ego:ego?selected.id:null}),'application/xml'));$('#edgescsv').onclick=()=>download('forme-archi.csv','Source,Target,Weight,Type\n'+edges.map(e=>`${e.source},${e.target},${e.weight},Undirected`).join('\n'),'text/csv');render();window.__network={get edges(){return edges},get nodes(){return shown},render};
}

function model3D(host,b,dims,explode=0){
 let T=THREE,scene=new T.Scene();scene.background=new T.Color('#153538');let camera=new T.PerspectiveCamera(38,1,.1,100),renderer;try{renderer=new T.WebGLRenderer({antialias:true,preserveDrawingBuffer:true})}catch{host.innerHTML='<p class="panel">WebGL non disponibile: resta consultabile il cartamodello 2D.</p>';return{destroy(){},setExplode(){}}}renderer.setPixelRatio(Math.min(devicePixelRatio,2));host.prepend(renderer.domElement);scene.add(new T.HemisphereLight(0xfff1d4,0x274b45,2.4));let light=new T.DirectionalLight(0xffffff,3);light.position.set(-3,5,5);scene.add(light);let group=new T.Group();scene.add(group);let g=BagGeometry.geometry(b,dims),scale=3/Math.max(g.w,g.h,g.d),w=g.w*scale,h=g.h*scale,d=g.d*scale;
 let shape=new T.Shape();g.p.forEach(([x,y],i)=>{i?shape.lineTo((x-g.w/2)*scale,(g.h/2-y)*scale):shape.moveTo((x-g.w/2)*scale,(g.h/2-y)*scale)});shape.closePath();let faceGeo=new T.ExtrudeGeometry(shape,{depth:.045,bevelEnabled:true,bevelSegments:2,steps:1,bevelSize:.015,bevelThickness:.012}),mat=new T.MeshStandardMaterial({color:b.color,roughness:.65,metalness:.04,side:T.DoubleSide}),front=new T.Mesh(faceGeo,mat),back=new T.Mesh(faceGeo,mat.clone());front.position.z=d/2;back.position.z=-d/2-.045;group.add(front,back);
 let verts=[],indices=[];g.p.forEach(([x,y],i)=>{let X=(x-g.w/2)*scale,Y=(g.h/2-y)*scale;verts.push(X,Y,-d/2,X,Y,d/2);let j=(i+1)%g.p.length;indices.push(i*2,i*2+1,j*2+1,i*2,j*2+1,j*2)});let bandGeo=new T.BufferGeometry();bandGeo.setAttribute('position',new T.Float32BufferAttribute(verts,3));bandGeo.setIndex(indices);bandGeo.computeVertexNormals();let band=new T.Mesh(bandGeo,new T.MeshStandardMaterial({color:b.color,roughness:.8,side:T.DoubleSide}));group.add(band);let edges=new T.LineSegments(new T.EdgesGeometry(faceGeo),new T.LineBasicMaterial({color:0xddc59a,transparent:true,opacity:.65}));front.add(edges);let handle=null;if(!['pochette','cuore','cilindro','box'].includes(b.shape)){let curve=new T.CatmullRomCurve3([new T.Vector3(-w*.25,h*.4,d*.2),new T.Vector3(-w*.22,h*.85,d*.2),new T.Vector3(w*.22,h*.85,d*.2),new T.Vector3(w*.25,h*.4,d*.2)]);handle=new T.Mesh(new T.TubeGeometry(curve,40,.035,8,false),mat.clone());group.add(handle)}let floor=new T.GridHelper(8,20,0x54736d,0x294b45);floor.position.y=-h/2-.1;scene.add(floor);let yaw=.5,pitch=.15,dist=7.5,drag=null,frame;
 function setExplode(v){front.position.z=d/2+v;back.position.z=-d/2-.045-v;band.scale.set(1+v*.12,1+v*.12,1);if(handle)handle.position.y=v*.5}setExplode(explode);
 function draw(){camera.position.set(dist*Math.sin(yaw)*Math.cos(pitch),dist*Math.sin(pitch)+.2,dist*Math.cos(yaw)*Math.cos(pitch));camera.lookAt(0,.2,0);renderer.render(scene,camera);frame=requestAnimationFrame(draw)}function resize(){renderer.setSize(host.clientWidth,host.clientHeight);camera.aspect=host.clientWidth/host.clientHeight;camera.updateProjectionMatrix()};let ro=new ResizeObserver(resize);ro.observe(host);resize();draw();let cv=renderer.domElement;cv.onpointerdown=e=>{drag=[e.clientX,e.clientY,yaw,pitch];cv.setPointerCapture(e.pointerId)};cv.onpointermove=e=>{if(drag){yaw=drag[2]-(e.clientX-drag[0])*.008;pitch=Math.max(-1.2,Math.min(1.2,drag[3]+(e.clientY-drag[1])*.008))}};cv.onpointerup=()=>drag=null;cv.onwheel=e=>{e.preventDefault();dist=Math.max(4,Math.min(15,dist*Math.exp(e.deltaY*.001)))};return{scene,camera,canvas:cv,setExplode,destroy(){cancelAnimationFrame(frame);ro.disconnect();scene.traverse(o=>{o.geometry?.dispose();if(o.material)Array.isArray(o.material)?o.material.forEach(m=>m.dispose()):o.material.dispose()});renderer.dispose();cv.remove()}};
}

function atelier(){main.innerHTML=intro('Atelier / superficie e volume','Scomporre.<br>Capire. Ricostruire.','Un laboratorio geometrico per ogni borsa. Modifica gli ingombri, esplora il volume e scarica le superfici per un primo prototipo di studio.')+`<div class="toolbar"><label>Scegli il modello<select id="bag">${bagOptions(Q.get('id'))}</select></label><a id="sheetlink" class="btn ghost">Scheda completa ↗</a><button id="restore" class="ghost">Ripristina quote</button></div><div id="atelierstatus" class="statusline"></div><div class="formgrid"><label>Larghezza (cm)<input id="w" type="number" min="5" max="100" step=".1"></label><label>Altezza (cm)<input id="h" type="number" min="5" max="100" step=".1"></label><label>Profondità (cm)<input id="d" type="number" min="1" max="60" step=".1"></label><label>Margine di cucitura (mm)<input id="seam" type="number" min="0" max="20" value="7" step="1"></label></div><div class="grid2 section"><div><div class="row between"><h3>Volume ricostruito</h3><span class="tag">Geometria didattica</span></div><div class="model" id="model"><p class="caption">Trascina per ruotare · rotella per zoomare</p></div><label style="margin-top:14px">Separa i pannelli<input id="explode" type="range" min="0" max="1.5" value="0" step=".01"></label></div><div><div class="row between"><h3>Cartamodello piano</h3><span class="tag">Scala SVG 1:1 in mm</span></div><div id="pattern" class="pattern-preview"></div><p class="caption" style="margin-top:12px">Scorri orizzontalmente per vedere la tavola. SVG a dimensione fisica; controlla il quadrato di 50 mm dopo la stampa. Per A4 usa una funzione di stampa a mosaico.</p></div></div><div class="row section"><button id="svg">Cartamodello SVG ↓</button><button id="dxf" class="ghost">Contorni DXF ↓</button><button id="modelpng" class="ghost">Vista 3D PNG ↓</button><button id="params" class="ghost">Parametri JSON ↓</button></div><div class="section grid2"><section class="panel"><div class="eyebrow">Distinta di studio</div><h2>Che cosa stai costruendo</h2><div id="parts"></div><ol><li>Stampa senza adattamento automatico e verifica la scala.</li><li>Taglia prima una tela di prova; riporta i riferimenti R sui bordi.</li><li>Prepara la fascia, inserisci l’apertura di prova e unisci le estremità corte.</li><li>Accoppia fronte e retro alla fascia seguendo i riferimenti. Verifica la coincidenza delle cuciture.</li><li>Valuta accesso, deformazione e rinforzi prima di scegliere il materiale finale.</li></ol></section><section class="panel"><div class="eyebrow">Limiti della ricostruzione</div><h2>Il modello e l’originale</h2><p>Non sono stati reperiti cartamodelli originali pubblicamente verificabili per questa selezione. Le 200 tavole sono ricostruzioni geometriche editoriali, non modelli delle maison.</p><p>Il sistema usa il perimetro campionato del profilo per dimensionare una fascia continua. Le borse aperte vengono qui trasformate in involucri chiusi con un’apertura di prova: serve a studiare il volume, non a replicare la costruzione originale.</p><p id="materialnote"></p><p class="note">Margini nelle curve e nelle concavità approssimati; fodere, rivoltamenti, spessori, rinforzi, tolleranze e attacchi della ferramenta richiedono sviluppo manuale. Aerogel, metallo e cesti ricevono soltanto uno schema d’ingombro. La tracolla opzionale è una striscia di studio, non viene riprodotta nel volume 3D.</p></section></div>${hint('Varia una sola quota alla volta: aumentando la profondità, la fascia cambia mentre il fronte resta identico. L’esploso mostra questa relazione senza simulare le deformazioni fisiche del materiale.')}`;
 let b,model,dims,svg,g;function render(){dims=['w','h','d'].map(id=>+$('#'+id).value);if(dims.some((v,i)=>!Number.isFinite(v)||v<[5,5,1][i]||v>[100,100,60][i])){toast('Inserisci quote valide entro i limiti indicati.');return}let seam=+$('#seam').value;if(!Number.isFinite(seam)||seam<0||seam>20)return;g=BagGeometry.geometry(b,dims,seam);let changed=dims.some((v,i)=>Math.abs(v-b.dims[i])>.001),pb={...b,dimensionStatus:changed?'ipotesi modificata dall’utente':b.dimensionStatus};svg=BagGeometry.pattern(pb,dims,seam);$('#pattern').innerHTML=svg;model?.destroy();model=model3D($('#model'),b,dims,+$('#explode').value);$('#parts').innerHTML=`<table><tr><th>Pezzo</th><th>Quantità / geometria</th></tr><tr><td>A + B · facce</td><td>2 pannelli · profilo ${b.shape}</td></tr><tr><td>C · fascia</td><td>Cucitura ${fmt(g.perimeter)} × ${fmt(g.d)} mm</td></tr><tr><td>D · tracolla opzionale</td><td>1200 mm × 25 mm finiti</td></tr><tr><td>Area netta involucro</td><td>${fmt((2*g.area+g.perimeter*g.d)/1e6)} m², senza sfrido, fodera o tracolla</td></tr><tr><td>Apertura di prova</td><td>${fmt(g.zip)} mm · posizione schematica</td></tr></table>`;$('#atelierstatus').innerHTML=`${tag(pb)} ${E(b.variant)}${changed?' · quote personalizzate':''}`;$('#materialnote').textContent=b.materialNote;history.replaceState(null,'','?id='+b.id)}function choose(){b=get($('#bag').value);['w','h','d'].forEach((id,i)=>$('#'+id).value=b.dims[i]);$('#sheetlink').href=link(b);render()};$('#bag').onchange=choose;$('#restore').onclick=choose;['w','h','d','seam'].forEach(id=>$('#'+id).onchange=render);$('#explode').oninput=()=>model?.setExplode(+$('#explode').value);$('#svg').onclick=()=>download(b.id+'-studio.svg',svg,'image/svg+xml');$('#dxf').onclick=()=>download(b.id+'-studio.dxf',BagGeometry.dxf(b,dims,+$('#seam').value),'application/dxf');$('#params').onclick=()=>download(b.id+'-parametri.json',JSON.stringify({id:b.id,dims_cm:dims,seam_mm:+$('#seam').value,sourceDims:b.dims,status:'ricostruzione geometrica editoriale',perimeter_mm:g.perimeter},null,2),'application/json');$('#modelpng').onclick=()=>{if(!model.canvas)return;let a=document.createElement('a');a.href=model.canvas.toDataURL();a.download=b.id+'-3d.png';a.click()};choose();window.__atelier={get model(){return model},get bag(){return b},get geometry(){return g},render};
}

function geography(){main.innerHTML=intro('Geografia / aziende e luoghi','Le coordinate<br>di una cultura materiale.','Sedi documentate e centri aziendali indicativi. La mappa distingue la società, il marchio e il luogo di produzione: non sono la stessa cosa.')+`<div class="toolbar"><label>Livello di verifica<select id="geofilter"><option value="all">Tutti · distinguendo i dati indicativi</option><option value="verified">Solo sedi documentate</option></select></label><label>Seleziona una città<select id="city"><option value="">Tutte le città</option>${options([...new Set(Object.values(A.brands).map(b=>b.city))].sort())}</select></label><button id="geocsv" class="ghost">Esporta sedi CSV ↓</button></div><div class="legend"><span><i style="background:#b4613e"></i>Sede documentata</span><span><i style="background:transparent;border:1px solid #b4613e"></i>Centro indicativo da verificare</span></div><div class="viz-layout"><div><div class="viz" id="geoviz" style="height:470px"></div><p class="caption" style="margin-top:12px">Carta schematica equirettangolare disegnata per l’atlante; sagome continentali semplificate, senza confini. Coordinate dei centri urbani, non degli edifici. Clicca un punto o scegli una città.</p></div><aside class="panel"><h3 id="geotitle">Le sedi nel campione</h3><div class="geo-list" id="geolist"></div></aside></div><section class="section panel"><h2>Tre luoghi, tre significati</h2><div class="grid3"><div><h3>Sede societaria</h3><p class="note">Indirizzo di un’entità giuridica. Ad esempio CHANEL Limited è registrata a Londra; questo non sposta automaticamente a Londra l’identità creativa della maison.</p></div><div><h3>Centro creativo o operativo</h3><p class="note">Il luogo in cui si sviluppano collezioni e si coordinano attività può differire dalla sede legale. I centri non verificati sono indicati con un cerchio vuoto.</p></div><div><h3>Produzione</h3><p class="note">Laboratori, fornitori e stabilimenti non si deducono dalla mappa. Un marchio può produrre in più paesi e cambiare filiera tra varianti.</p></div></div></section>${hint('Filtra le sole sedi documentate per una lettura più rigorosa. A una singola città possono corrispondere molte aziende: l’elenco laterale le mantiene separate.')}`;
 const land=[[-168,70,-140,70,-125,60,-123,49,-110,32,-98,16,-84,10,-78,24,-82,30,-65,48,-55,55,-80,64,-100,75],[-80,12,-70,10,-50,0,-35,-7,-47,-24,-58,-40,-68,-55,-75,-40,-80,-5],[-52,60,-25,72,-40,83,-62,80],[-11,36,-10,58,10,71,35,70,45,55,30,42,10,36],[-17,35,10,37,34,31,52,12,40,-8,31,-34,18,-35,10,-10,-5,5,-17,15],[30,40,45,65,85,76,140,72,179,64,155,45,135,35,120,20,108,4,98,10,82,8,70,25,50,12,35,32],[112,-11,135,-11,154,-24,147,-39,128,-34,113,-25],[130,31,141,45,146,42,138,32],[166,-34,178,-40,171,-47],[47,-13,50,-24,44,-26,43,-17]];
 function xy(lon,lat){return [(lon+180)/360*1000,(85-lat)/145*440]}
 function render(){let verified=$('#geofilter').value==='verified',city=$('#city').value,all=Object.entries(A.brands).filter(([k,v])=>!verified||v.verified),groups={};all.forEach(([b,v])=>(groups[v.city]??=[]).push([b,v]));let svg=`<svg viewBox="0 0 1000 470" role="img" aria-label="Carta schematica delle città aziendali"><rect width="1000" height="470" fill="#e8ece2"/>`;for(let lon=-180;lon<=180;lon+=30){let [x]=xy(lon,0);svg+=`<path d="M${x},0V440" stroke="#d6dfd3" stroke-width="1"/>`}for(let lat=-60;lat<=80;lat+=20){let [x,y]=xy(0,lat);svg+=`<path d="M0,${y}H1000" stroke="#d6dfd3" stroke-width="1"/>`};svg+=land.map(poly=>`<polygon points="${Array.from({length:poly.length/2},(_,i)=>xy(poly[i*2],poly[i*2+1]).join(',')).join(' ')}" fill="#c5ceba" stroke="#b4c0ac" stroke-width="1"/>`).join('');Object.entries(groups).forEach(([c,bs])=>{let v=bs[0][1],[x,y]=xy(v.lon,v.lat),r=5+Math.log(bs.length+1)*2;svg+=`<g data-city="${E(c)}" tabindex="0" role="button" aria-label="${E(c)}: ${bs.length} marchi" style="cursor:pointer"><circle cx="${x}" cy="${y}" r="${r+6}" fill="transparent"/><circle cx="${x}" cy="${y}" r="${r}" fill="${bs.some(([b,v])=>v.verified)?'#ad5b3b':'#e8ece2'}" stroke="${city===c?'#233f3d':'#ad5b3b'}" stroke-width="${city===c?3:1.5}"/><title>${E(c)} · ${bs.length} marchi</title></g>`});svg+='<text x="25" y="461" class="map-label">N ↑ · S ↓ · W ← · E → / LOCALIZZAZIONI URBANE, NON SITI PRODUTTIVI</text></svg>';$('#geoviz').innerHTML=svg;let items=all.filter(([b,v])=>!city||v.city===city);$('#geotitle').textContent=city||`${all.length} marchi · ${Object.keys(groups).length} città`;$('#geolist').innerHTML=items.map(([b,v])=>`<div class="geo-item"><h3>${E(b)}</h3><p>${E(v.city)}, ${E(v.country)}<br>${E(v.entity)}<br><span class="tag ${v.verified?'ok':'warn'}">${E(v.type)}</span></p>${v.source?`<a class="small" href="${E(S[v.source].url)}" target="_blank" rel="noopener">Fonte societaria ↗</a>`:'<span class="caption">Localizzazione editoriale non verificata.</span>'}<br><a class="small" href="index.html?brand=${encodeURIComponent(b)}">${B.filter(x=>x.brand===b).length} borse nell’atlante →</a></div>`).join('')||'<p>Nessuna sede corrispondente al filtro.</p>';$$('[data-city]').forEach(e=>{let go=()=>{$('#city').value=e.dataset.city;render()};e.onclick=go;e.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();go()}}})}
 $('#geofilter').onchange=render;$('#city').onchange=render;$('#geocsv').onclick=()=>{let rows=[['marchio','entita','citta','paese','latitudine_centro','longitudine_centro','tipo','verificata','fonte'],...Object.entries(A.brands).map(([b,v])=>[b,v.entity,v.city,v.country,v.lat,v.lon,v.type,v.verified,v.source?S[v.source].url:''])];download('forme-sedi.csv','\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n'),'text/csv')};render();window.__geo={render};
}

function method(){main.innerHTML=intro('Metodo / dati e responsabilità editoriale','Sapere cosa<br>stiamo confrontando.',M.selection)+`<div class="stats"><div><strong>200</strong><span>Schede e disegni</span></div><div><strong>${M.historicalEpisodes}</strong><span>Con episodi documentati</span></div><div><strong>${M.dimensionVerified}</strong><span>Terne dimensionali verificate</span></div><div><strong>${M.hqVerified}</strong><span>Sedi documentate</span></div></div><div class="grid2 section"><section class="panel"><h2>Tre livelli da tenere distinti</h2><h3>1. Dato documentato</h3><p>Una fonte consultata sostiene un’affermazione precisa. Le dimensioni verificate appartengono alla variante citata, non all’intera famiglia. Le fonti societarie riguardano l’entità indicata.</p><h3>2. Interpretazione curatoriale</h3><p>Significati, motivi della selezione e punteggi esprimono una lettura del design. La categoria «Nuovi codici» include candidati contemporanei: non tutti hanno lo stesso riconoscimento storico.</p><h3>3. Ipotesi di studio</h3><p>Quote non documentate, localizzazioni indicative e geometrie ricostruite sono assunzioni esplicite. Non usarle come misure di un prodotto commerciale o cartamodelli pronti per produzione.</p></section><section class="panel"><h2>Cosa resta aperto</h2><p>${200-M.historicalEpisodes} schede non hanno ancora un episodio storico specifico consolidato. Le date di riferimento non verificate sono mostrate come tali, e le fonti generali di marchio non vengono presentate come prova del singolo modello.</p><p>${200-M.dimensionVerified} terne dimensionali sono ipotesi geometriche. Tutti i cartamodelli sono ricostruzioni didattiche: non sono stati reperiti originali pubblicamente verificabili.</p><p>La selezione privilegia accessori commercializzati da marchi di moda europei e nordamericani. Non è una storia globale di tutte le borse, né una graduatoria scientifica delle “200 più importanti”.</p><p class="note">Le illustrazioni SVG e i volumi 3D sono rappresentazioni analitiche originali. Non sono fotografie, scansioni o ricostruzioni esatte degli esemplari. Le fonti rimandano alle immagini e alle descrizioni dei titolari.</p></section></div><section class="panel section"><h2>Come sono attribuiti i punteggi</h2><div class="table-wrap"><table><thead><tr><th>Variabile</th><th>Regola di codifica</th></tr></thead><tbody><tr><td>Rigidità, curvatura, formalità, utilità</td><td>Valori iniziali per archetipo: box 5/1/5/1; tote 2/1/2/5; hobo 1/5/2/3; zaino 2/2/1/5. Tote in pelle: rigidità 3. Pochette metallica: rigidità 5. Tutte le righe sono esportate nel JSON.</td></tr><tr><td>Visibilità del logo</td><td>5 quando la descrizione include logo, monogramma, iniziali, doppia, FF, Medusa, Cassandre, CD, triangolo, scritta o firma grande; altrimenti 1.</td></tr><tr><td>Hardware</td><td>5 per catene, borchie, lucchetti, anelli, cornici, Medusa o teschi; 3 per fibbie, fermagli, serrature o Gancini; altrimenti 1.</td></tr><tr><td>Lavorazione visibile</td><td>5 per intreccio, ricamo, bambù, traforo, cristalli o fibre; 4 per trapuntatura; 3 per pelle; altrimenti 2.</td></tr><tr><td>Espressività</td><td>5 per cuore, ovale, cesto o segni scultorei dichiarati; 4 per logo o hardware dominante; altrimenti 2.</td></tr></tbody></table></div><p class="note">Queste regole rendono la codifica riproducibile, ma introducono semplificazioni e correlazioni costruite a monte. “Formalità” e “utilità” non sono misure validate; la PCA esplora questa griglia curatoriale.</p></section><div class="grid2 section"><section class="panel"><h2>PCA: il calcolo</h2><p>Per ogni matrice X, ogni colonna viene centrata e divisa per la deviazione standard campionaria. Si calcola C = ZᵀZ / (n−1), poi si ordinano gli autovalori e si proietta Z sui primi tre autovettori.</p><p>La varianza spiegata è il rapporto tra ciascun autovalore e la loro somma. Le componenti sono ortogonali nello spazio standardizzato. Nessun punteggio di popolarità, prezzo o provenienza geografica entra nel calcolo.</p><p class="note">Le tre matrici usano sempre le 200 righe. I filtri visivi non modificano il modello. Gli indicatori binari dei materiali sono standardizzati: i materiali rari possono incidere molto sugli assi. La PCA delle forme incorpora molte dimensioni stimate.</p></section><section class="panel"><h2>Rete: somiglianza o correlazione?</h2><p>La vista Gower misura la somiglianza media su otto codici. Pearson confronta l’andamento dei profili; Jaccard confronta insiemi di termini materici. Cambiare metrica cambia il significato degli archi.</p><p>GEXF è il formato consigliato per Gephi. GraphML è un’alternativa; GXL è incluso interpretando la richiesta “glx”. Non viene creato un file con estensione non standard mascherata.</p><p class="note">La rete preesportata usa Gower ≥ 0,84 e l’unione dei quattro vicini migliori per nodo. La rete interattiva esporta invece lo stato corrente, incluso l’eventuale vicinato selezionato.</p></section></div><section class="section"><h2>Scarica, verifica, riusa</h2><div class="grid3 download-grid"><div><a href="dati/catalogo.json" download><b>Dataset completo JSON ↓</b><span>200 schede, fonti, coordinate, variabili, PCA.</span></a><a href="dati/catalogo.csv" download><b>Catalogo CSV ↓</b><span>Campi descrittivi, quote e punteggi.</span></a></div><div>${['semantica','forma','materiali'].map(k=>`<a href="dati/pca-${k}.csv" download><b>PCA ${k} ↓</b><span>Variabili originali e tre componenti.</span></a>`).join('')}</div><div>${['gexf','graphml','gxl'].map(k=>`<a href="dati/rete.${k}" download><b>Rete .${k} ↓</b><span>200 nodi · configurazione iniziale.</span></a>`).join('')}</div></div></section><section class="panel section sources"><h2>Registro delle fonti</h2><p class="note">Fonti primarie delle maison e del museo, con contributi editoriali o di cataloghi d’asta dove indicato. Ogni riferimento dichiara il proprio perimetro; consultazione 30 settembre 2026.</p>${sourceLinks(Object.keys(S))}</section><section class="panel section"><h2>Il tuo percorso</h2><p>${seen.length} schede visitate · ${favorites.length} preferiti · ${read('quiz',[]).length} esercizi riconosciuti. Il taccuino viene salvato solo in questo browser, quando la memoria locale è disponibile.</p><div class="progress"><i style="width:${seen.length/2}%"></i></div><button id="exportnotes" class="ghost">Esporta il taccuino JSON ↓</button></section>`;$('#exportnotes').onclick=()=>download('forme-taccuino.json',JSON.stringify({seen,favorites,quiz:read('quiz',[])},null,2),'application/json')}

({catalogo:catalog,scheda:sheet,confronto:comparison,mappe:maps,rete:networkPage,laboratorio:atelier,geografia:geography,metodo:method}[PAGE]||catalog)();tray();window.__atlas={data:A,page:PAGE};
